import { after } from 'next/server';

export default function WelcomeAnalytics() {
  // Schedule the logging to happen after the response is sent
  after(async () => {
    // Mock analytics logging
    await new Promise((resolve) => setTimeout(resolve, 100)); // Simulate network delay
    console.log('[Analytics] Page view logged successfully.');
  });

  return (
    <div className="p-4 border rounded-lg bg-gray-50 dark:bg-gray-900">
      <h1 className="text-2xl font-bold mb-2">Welcome to our site!</h1>
      <p className="text-gray-600 dark:text-gray-300">
        We are happy to have you here. Your visit has been anonymously logged for analytics purposes.
      </p>
    </div>
  );
}

import WelcomeAnalytics from './components/WelcomeAnalytics';

export default function Home() {
  return (
    <main className="flex min-h-screen flex-col items-center justify-between p-24">
      <div className="z-10 max-w-5xl w-full items-center justify-between font-mono text-sm lg:flex">
        <WelcomeAnalytics />
      </div>
    </main>
  );
}

